  'PDF, DOCX, PPTX, XLSX, TXT · max 8 MB': { tl: 'PDF, DOCX, PPTX, XLSX, TXT · max 8 MB', es: 'PDF, DOCX, PPTX, XLSX, TXT · máx. 8 MB', vi: 'PDF, DOCX, PPTX, XLSX, TXT · tối đa 8 MB', wuu: 'PDF、DOCX、PPTX、XLSX、TXT · 最大 8 MB', sichuan: 'PDF、DOCX、PPTX、XLSX、TXT · 最大 8 MB' },
